datasource db {
  provider = "postgresql"
  // Wasp requires that the url is set to the DATABASE_URL environment variable.
  url      = env("DATABASE_URL")
}

// Wasp requires the `prisma-client-js` generator to be present.
generator client {
  provider = "prisma-client-js"
}

model Sample {
  id             Int      @id @default(autoincrement())
  metric         String
  value          Float
  recordedAt     DateTime
  idempotencyKey String   @unique
  ingestedAt     DateTime @default(now())
}

model RollupResult {
  id        Int      @id @default(autoincrement())
  metric    String   @unique
  count     Int
  p95       Float?
  avg       Float?
  delta     Float?
  updatedAt DateTime
}

export async function rollupMetrics(args: any, context: any) {
  console.log("Job executed with args:", args);
}

export async function ingestSample(req: any, res: any, context: any) {
  res.json({ message: "ingestSample skeleton" });
}

export async function enqueueRollup(req: any, res: any, context: any) {
  res.json({ message: "enqueueRollup skeleton" });
}

export async function getDashboard(req: any, res: any, context: any) {
  res.json([]);
}

import { app, page, route, api, job } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { ingestSample, enqueueRollup, getDashboard } from "./src/apis" with { type: "ref" };
import { rollupMetrics } from "./src/jobs/rollupMetrics" with { type: "ref" };

export default app({
  name: "waspmetrics",
  wasp: { version: "^0.25.0" },
  title: "waspmetrics",
  head: ["<link rel='icon' href='/favicon.ico' />"],
  spec: [
    route("RootRoute", "/", page(MainPage)),
    api("POST", "/samples", ingestSample, { entities: ["Sample"], auth: false }),
    api("POST", "/rollup", enqueueRollup, { entities: ["Sample", "RollupResult"], auth: false }),
    api("GET", "/dashboard", getDashboard, { entities: ["Sample", "RollupResult"], auth: false }),
    job(rollupMetrics, {
      executor: "PgBoss",
      entities: ["Sample", "RollupResult"],
      schedule: {
        cron: "23 3 * * *",
        args: { reason: "cron" }
      }
    })
  ],
});

